    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");

        uint potBefore = c.pot();
        uint balanceBefore = address(c).balance;
        bool reverted;

        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint potAfter = c.pot();
